python3 - <<'PY'
import pathlib
p = pathlib.Path("tests/ir_backend_smoke_test.rs")
s = p.read_text()
old = '''        if is_diagnostic(part) {
            continue;
        }
        let introduces_diagnostic = *part == "\\n"
            && parts
                .get(index + 1)
                .is_some_and(|next| is_diagnostic(next));
        if introduces_diagnostic {
            continue;
        }
        kept.push_str(part);'''
new = '''        if is_diagnostic(part) {
            // php prefixes every diagnostic with a newline, and that newline is glued to the end
            // of whatever the program printed last — it is not a line of its own to skip.
            if kept.ends_with('\\n') {
                kept.pop();
            }
            continue;
        }
        let _ = index;
        kept.push_str(part);'''
assert s.count(old) == 1, s.count(old)
p.write_text(s.replace(old, new))
print("framing fixed")
